/// The status a rate-limited request fails with (Too Many Requests).
const int _rateLimitedStatus = 429;

/// A server whose every request answers its own ordinal (1, 2, ...), unless it
/// is told to refuse the next one: that request fails rate-limited, carrying
/// [retryAfterMs].
class _OrdinalServer {
  _OrdinalServer(this.retryAfterMs);

  final int? retryAfterMs;
  int requests = 0;

  /// How many requests it answered (a refused one is not answered).
  int answers = 0;
  bool _refuseNext = false;

  void refuse() {
    if (_refuseNext) {
      throw StateError("The next request is already refused; a row repeats 'limit'.");
    }
    _refuseNext = true;
  }

  Future<int> answer() async {
    requests += 1;
    if (_refuseNext) {
      _refuseNext = false;
      throw CruftFreeException('Too Many Requests', ProblemDetails(type: ProblemDetails.unknownProblemType, title: 'Too Many Requests', detail: '', status: _rateLimitedStatus, errors: const [], retryAfterMs: retryAfterMs));
    }
    answers += 1;
    return requests;
  }
}

const Duration _pollEvery = Duration(seconds: 2);

/// The answer of the request at [index]: the next of [answers], the last repeating.
int _answerAt(List<int> answers, int index) => answers[index < answers.length ? index : answers.length - 1];

/// One row of the polling case table.
typedef _PollCase = ({String name, List<int> answers, int? stopValue, int? maxPolls, List<String> events, int requests, bool exhausted, bool polling});

/// One row of the gate case table: whether the condition holds when the binding
/// is shown, the events after, the wait a refused request carries, how many
/// requests it issued (and how many poll ticks the server answered), the value
/// it shows (each answered request answers its ordinal), whether it ends
/// paused and the `pausedForMs` the last refusal started with.
typedef _GateCase = ({String name, bool startsOpen, List<String> events, int? retryAfterMs, int requests, int ticks, int? shown, bool paused, int? pauseMs});
